def _pe(val: str) -> str: return urllib.parse.quote(str(val), safe="-._~")

def build_oauth1_header(method: str, url: str, consumer_key: str, consumer_secret: str, access_token: str, access_token_secret: str) -> str: parsed = urllib.parse.urlsplit(url); base_url = f"{parsed.scheme}{config.SEP}{parsed.netloc}{parsed.path}"; q_params = urllib.parse.parse_qsl(parsed.query, keep_blank_values=True); oauth_p = {"oauth_consumer_key": consumer_key, "oauth_nonce": secrets.token_hex(16), "oauth_signature_method": "HMAC-SHA1", "oauth_timestamp": str(int(time.time())), "oauth_token": access_token, "oauth_version": "1.0"}; all_p = sorted([(_pe(k), _pe(v)) for k, v in q_params] + [(_pe(k), _pe(v)) for k, v in oauth_p.items()], key=lambda x: (x[0], x[1])); param_str = "&".join(f"{k}={v}" for k, v in all_p); base_str = "&".join([method.upper(), _pe(base_url), _pe(param_str)]); sign_key = f"{_pe(consumer_secret)}&{_pe(access_token_secret)}"; digest = hmac.new(sign_key.encode("utf-8"), base_str.encode("utf-8"), hashlib.sha1).digest(); oauth_p["oauth_signature"] = base64.b64encode(digest).decode("utf-8"); return "OAuth " + ", ".join(f'{_pe(k)}="{_pe(v)}"' for k, v in sorted(oauth_p.items()))

def _auth_header(method: str, url: str, creds: Dict[str, str], require_user: bool) -> str: has_o1 = all(creds.get(k) for k in ("X_API_KEY", "X_API_SECRET", "X_ACCESS_TOKEN", "X_ACCESS_TOKEN_SECRET")); return (f"Bearer {creds['X_USER_ACCESS_TOKEN']}" if creds.get("X_USER_ACCESS_TOKEN") else (build_oauth1_header(method, url, creds["X_API_KEY"], creds["X_API_SECRET"], creds["X_ACCESS_TOKEN"], creds["X_ACCESS_TOKEN_SECRET"]) if has_o1 else (f"Bearer {creds['X_BEARER_TOKEN']}" if ((not require_user) and creds.get("X_BEARER_TOKEN")) else "")))

def x_api_request(conn: sqlite3.Connection, method: str, url: str, json_body: Optional[Dict[str, Any]] = None, require_user_context: bool = False) -> Dict[str, Any]: creds = get_all_creds(conn); auth = _auth_header(method, url, creds, require_user_context); (None if auth else (_ for _ in ()).throw(RuntimeError("Missing X API credentials. Please configure OAuth 1.0a keys or OAuth 2.0 User Access Token in Step 3."))); headers = {"Accept": "application/json", "User-Agent": "GenAIFundFDEOutreach/6.0", "Authorization": auth}; (headers.update({"Content-Type": "application/json"}) if json_body is not None else None); data_b = (json.dumps(json_body).encode("utf-8") if json_body is not None else None); ok, res = config.fetch_json(url, headers=headers, data=data_b, method=method.upper(), timeout=14); return (res if (ok and isinstance(res, dict)) else (_ for _ in ()).throw(RuntimeError(str(res))))

def resolve_tweet_oembed_text(tweet_url: str) -> Optional[str]: m_st = re.search(r"(?:x|twitter)" + re.escape(config.DOM) + r"/([A-Za-z0-9_]+)/status/(\d+)", tweet_url or ""); uname, tid = (m_st.group(1), m_st.group(2)) if m_st else ("", ""); ok1, d1 = (config.fetch_json(f"{config.FXTWITTER_API_BASE}/{urllib.parse.quote(uname)}/status/{urllib.parse.quote(tid)}") if m_st else (False, {})); t1 = ((d1.get("tweet") or {}).get("text") if (ok1 and isinstance(d1, dict)) else ""); ok2, d2 = (config.fetch_json(f"{config.X_OEMBED_URL}?url={urllib.parse.quote(tweet_url.strip())}&omit_script=true") if (not t1 and tweet_url and ("x" + config.DOM + "/" in tweet_url or "twitter" + config.DOM + "/" in tweet_url)) else (False, {})); raw_h = (d2.get("html", "") if (ok2 and isinstance(d2, dict)) else ""); m_p = re.search(r"<p[^>]*>(.*?)</p>", raw_h, flags=re.DOTALL | re.IGNORECASE); t2 = (html.unescape(re.sub(r"\s+", " ", re.sub(r"<[^>]+>", " ", m_p.group(1)))).strip() if m_p else ""); return (str(t1).strip() if t1 else (t2 or None))

def resolve_real_x_user_public(username: str) -> Optional[Dict[str, Any]]: clean = username.strip().lstrip("@"); ok_fx, dfx = (config.fetch_json(f"{config.FXTWITTER_API_BASE}/{urllib.parse.quote(clean)}") if clean else (False, {})); u_fx = ((dfx.get("user") or {}) if (ok_fx and isinstance(dfx, dict)) else {}); ok_vx, dvx = (config.fetch_json(f"{config.VXTWITTER_API_BASE}/{urllib.parse.quote(clean)}") if (clean and not u_fx.get("id")) else (False, {})); u_vx = ((dvx.get("user") or dvx) if (ok_vx and isinstance(dvx, dict)) else {}); ok_w, dw = (config.fetch_json(f"{config.X_SYNDICATION_USER_URL}?screen_names={urllib.parse.quote(clean)}") if (clean and not u_fx.get("id") and not u_vx.get("id")) else (False, [])); u_w = (dw[0] if (ok_w and isinstance(dw, list) and dw) else {}); uid = str(u_fx.get("id") or u_vx.get("id") or u_vx.get("id_str") or u_w.get("id") or ""); sname = str(u_fx.get("screen_name") or u_vx.get("screen_name") or u_w.get("screen_name") or clean); dname = str(u_fx.get("name") or u_vx.get("name") or u_w.get("name") or sname); bio = str(u_fx.get("description") or u_vx.get("description") or ""); loc = str(u_fx.get("location") or "Southeast Asia / Global"); followers = int(u_fx.get("followers") or u_vx.get("followers_count") or u_w.get("followers_count") or 0); return ({"participant_id": uid, "username": sname, "display_name": dname, "location": loc, "bio": bio or f"AI & Robotics builder on X (@{sname}).", "followers_count": followers, "recent_posts": [], "has_real_numeric_id": bool(uid and uid.isdigit())} if (clean and (uid or bio)) else None)

